  if (Object.hasOwn(env, 'SYNC_BATCH')) {
    if (!/^\d+$/.test(env.SYNC_BATCH)) throw new Error('Invalid SYNC_BATCH');
    result.batchSize = Number(env.SYNC_BATCH);
